            "badgeText": "روانشناسی عمیق",
            "badgeColor": "rose",
            "contentHtml": "\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div class=\"point-icon icon-rose\">💔</div>\n          <h2 class=\"card-title rose\">احساس منفی؛ کاتالیزور اصلی رفتار ناخودآگاه</h2>\n        </div>\n        <div class=\"point-list\">\n          <div class=\"point-item\">\n            <div class=\"point-icon icon-rose\">۱</div>\n            <div><strong>فرار از درد:</strong> انسان بیش از آنکه به دنبال لذت باشد، برای گریز از ناراحتی‌های روانی کوچک اقدام می‌کند.</div>\n          </div>\n          <div class=\"point-item\">\n            <div class=\"point-icon icon-rose\">۲</div>\n            <div><strong>نگاشت احساسات منفی به محصولات پیشرو:</strong>\n              <br>• <span class=\"tag tag-rose\">تنهایی:</span> اینستاگرام و فیسبوک.\n              <br>• <span class=\"tag tag-amber\">عدم قطعیت:</span> جستجوی گوگل.\n              <br>• <span class=\"tag tag-cyan\">بی‌حوصلگی:</span> یوتیوب و تیک‌تاک.\n              <br>• <span class=\"tag tag-purple\">ترس از عقب‌ماندن:</span> ایمیل و اسلک.\n            </div>\n          </div>\n          <div class=\"point-item\">\n            <div class=\"point-icon icon-rose\">۳</div>\n            <div><strong>شرطی‌سازی کامل:</strong> کاربر قبل از آنکه بفهمد ناراحت است، دستش به سمت باز کردن اپ رفته است!</div>\n          </div>\n        </div>\n        <div class=\"highlight-box rose\">\n          <strong>حقیقت تلخ:</strong> اگر ندانید کاربر برای فرار از چه حس دردناکی به شما پناه می‌آورد، نمی‌توانید محصولی قلاب‌ساز بسازید.\n        </div>\n      </div>\n    ",
            "visualSvg": "\n      <svg width=\"680\" height=\"480\" viewBox=\"-15 -15 710 510\" style=\"overflow: visible;\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n        <g transform=\"translate(35, 40)\">\n          <rect x=\"0\" y=\"0\" width=\"270\" height=\"90\" rx=\"14\" fill=\"rgba(251,113,133,0.1)\" stroke=\"#fb7185\" stroke-width=\"1.5\"/>\n          <text x=\"135\" y=\"40\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"22\" font-weight=\"bold\">حس بی‌حوصلگی</text>\n          <text x=\"135\" y=\"70\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"16\">نیاز به سرگرمی فوری</text>\n\n          <path d=\"M 285 45 L 325 45\" stroke=\"#38bdf8\" stroke-width=\"3\" stroke-dasharray=\"4 4\"/>\n\n          <rect x=\"340\" y=\"0\" width=\"270\" height=\"90\" rx=\"14\" fill=\"rgba(56,189,248,0.1)\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n          <text x=\"475\" y=\"40\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"22\" font-weight=\"bold\">YouTube / TikTok</text>\n          <text x=\"475\" y=\"70\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"16\">جریان بی‌پایان ویدیو</text>\n        </g>\n\n        <g transform=\"translate(35, 145)\">\n          <rect x=\"0\" y=\"0\" width=\"270\" height=\"90\" rx=\"14\" fill=\"rgba(251,113,133,0.1)\" stroke=\"#fb7185\" stroke-width=\"1.5\"/>\n          <text x=\"135\" y=\"40\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"22\" font-weight=\"bold\">احساس تنهایی</text>\n          <text x=\"135\" y=\"70\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"16\">نیاز به تایید و ارتباط</text>\n\n          <path d=\"M 285 45 L 325 45\" stroke=\"#34d399\" stroke-width=\"3\" stroke-dasharray=\"4 4\"/>\n\n          <rect x=\"340\" y=\"0\" width=\"270\" height=\"90\" rx=\"14\" fill=\"rgba(52,211,153,0.1)\" stroke=\"#34d399\" stroke-width=\"1.5\"/>\n          <text x=\"475\" y=\"40\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"22\" font-weight=\"bold\">Instagram / FB</text>\n          <text x=\"475\" y=\"70\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"16\">دیدن زندگی دوستان و لایک</text>\n        </g>\n\n        <g transform=\"translate(35, 250)\">\n          <rect x=\"0\" y=\"0\" width=\"270\" height=\"90\" rx=\"14\" fill=\"rgba(251,113,133,0.1)\" stroke=\"#fb7185\" stroke-width=\"1.5\"/>\n          <text x=\"135\" y=\"40\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"22\" font-weight=\"bold\">شک و عدم قطعیت</text>\n          <text x=\"135\" y=\"70\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"16\">ترس از جهل و ندانستن</text>\n\n          <path d=\"M 285 45 L 325 45\" stroke=\"#fbbf24\" stroke-width=\"3\" stroke-dasharray=\"4 4\"/>\n\n          <rect x=\"340\" y=\"0\" width=\"270\" height=\"90\" rx=\"14\" fill=\"rgba(251,191,36,0.1)\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n          <text x=\"475\" y=\"40\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"22\" font-weight=\"bold\">Google Search</text>\n          <text x=\"475\" y=\"70\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"16\">پاسخ قطعی در چند ثانیه</text>\n        </g>\n\n        <rect x=\"130\" y=\"375\" width=\"420\" height=\"55\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#fb7185\" stroke-width=\"2\"/>\n        <text x=\"340\" y=\"410\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"19\" font-weight=\"bold\">محصول شما تسکین‌دهنده کدام حس کاربر است؟</text>\n      </svg>\n    "
