            "visualSvg": "\n      <svg width=\"680\" height=\"480\" viewBox=\"-15 -15 710 510\" style=\"overflow: visible;\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n        <g transform=\"translate(35, 50)\">\n          <rect x=\"0\" y=\"0\" width=\"610\" height=\"100\" rx=\"16\" fill=\"rgba(56,189,248,0.08)\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n          <text x=\"305\" y=\"45\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"22\" font-weight=\"bold\">۱. لذت (Pleasure) ⇄ درد (Pain)</text>\n          <text x=\"305\" y=\"78\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"18\">پاسخ‌های غریزی بیولوژیکی • تسکین فوری یا کسب حس خوشایند</text>\n        </g>\n\n        <g transform=\"translate(35, 175)\">\n          <rect x=\"0\" y=\"0\" width=\"610\" height=\"100\" rx=\"16\" fill=\"rgba(251,191,36,0.08)\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n          <text x=\"305\" y=\"45\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"22\" font-weight=\"bold\">۲. امید (Hope) ⇄ ترس (Fear)</text>\n          <text x=\"305\" y=\"78\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"18\">پیش‌بینی آینده • امید به موفقیت شغلی یا ترس از عقب‌ماندن</text>\n        </g>\n\n        <g transform=\"translate(35, 300)\">\n          <rect x=\"0\" y=\"0\" width=\"610\" height=\"100\" rx=\"16\" fill=\"rgba(192,132,252,0.08)\" stroke=\"#c084fc\" stroke-width=\"2\"/>\n          <text x=\"305\" y=\"45\" text-anchor=\"middle\" fill=\"#c084fc\" font-size=\"22\" font-weight=\"bold\">۳. پذیرش اجتماعی (Acceptance) ⇄ طرد (Rejection)</text>\n          <text x=\"305\" y=\"78\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"18\">موتور محرک لایک‌ها و ارتباطات اجتماعی • حفظ جایگاه در قبیله</text>\n        </g>\n      </svg>\n    "
